"""Tiny waitlist manager for small restaurants: add parties, quote wait times, text-ready list."""
import time
from dataclasses import dataclass, field

@dataclass
class Party:
    name: str
    size: int
    phone: str
    added: float = field(default_factory=time.time)

class Waitlist:
    def __init__(self, avg_turn_minutes=45):
        self.parties = []
        self.avg_turn = avg_turn_minutes

    def add(self, name, size, phone):
        self.parties.append(Party(name, size, phone))
        return self.quote(len(self.parties) - 1)

    def quote(self, index):
        return index * self.avg_turn

    def seat_next(self, table_size):
        for i, p in enumerate(self.parties):
            if p.size <= table_size:
                return self.parties.pop(i)
        return None

if __name__ == "__main__":
    w = Waitlist()
    print("Quoted wait:", w.add("Lee", 2, "555-0100"), "min")
    print("Quoted wait:", w.add("Garcia", 4, "555-0101"), "min")
    print("Seated:", w.seat_next(2).name)
EOF
